#[test]
fn choice_matches() {
    let pop: Vec<usize> = (0..7).collect();
    for b in &fixtures().seeds {
        let mut r = rng_for(b);
        let got: Vec<usize> = (0..10).map(|_| *r.choice(&pop)).collect();
        assert_eq!(got, b.choice7, "choice(range(7)) for seed {:?}", b.seed);
    }
}

#[test]
fn choices_match() {
    let weights = [0.1, 0.4, 0.2, 0.25, 0.05];
    let pop5: Vec<usize> = (0..5).collect();
    let pop4: Vec<usize> = (0..4).collect();
    let abc = ["a".to_string(), "b".to_string(), "c".to_string()];
    for b in &fixtures().seeds {
        let mut r = rng_for(b);
        let got = r.choices(&pop5, Some(&weights), None, 10);
        assert_eq!(
            got, b.choices_weighted,
            "choices(weights=...) for seed {:?}",
            b.seed
        );

        let mut r = rng_for(b);
        let got = r.choices(&pop5, None, None, 10);
        assert_eq!(
            got, b.choices_unweighted,
            "choices() unweighted for seed {:?}",
            b.seed
        );

        let mut r = rng_for(b);
        let got = r.choices(&pop4, None, Some(&[1.0, 3.0, 3.0, 10.0]), 10);
        assert_eq!(
            got, b.choices_cum,
            "choices(cum_weights=...) for seed {:?}",
            b.seed
        );

        let mut r = rng_for(b);
        let got = r.choices(&abc, Some(&[5.0, 1.0, 4.0]), None, 10);
        assert_eq!(
            got, b.choices_intweights,
            "choices(int weights) for seed {:?}",
            b.seed
        );
    }
}

#[test]
fn sample_matches_both_branches() {
    for b in &fixtures().seeds {
        // n=50, k=8: setsize = 21 + 4**ceil(log4(24)) = 21 + 64 -> pool branch.
        let mut r = rng_for(b);
        assert_eq!(
            r.sample_indices(50, 8),
            b.sample_pool,
            "sample(range(50), 8) for seed {:?}",
            b.seed
        );
        // n=500, k=3: setsize = 21 -> set branch.
        let mut r = rng_for(b);
        assert_eq!(
            r.sample_indices(500, 3),
            b.sample_set,
            "sample(range(500), 3) for seed {:?}",
            b.seed
        );
        // k=6: setsize = 21 + 4**ceil(log4(18)) = 21 + 64 = 85.
        let mut r = rng_for(b);
        assert_eq!(
            r.sample_indices(60, 6),
            b.sample_pool_k6,
            "sample(range(60), 6) for seed {:?}",
            b.seed
        );
        let mut r = rng_for(b);
        assert_eq!(
            r.sample_indices(100, 6),
            b.sample_set_k6,
            "sample(range(100), 6) for seed {:?}",
            b.seed
        );
        // The cloning form agrees with the index form.
        let pop: Vec<u32> = (0..50).map(|i| i * 10).collect();
        let mut r = rng_for(b);
        let got = r.sample(&pop, 8);
        let want: Vec<u32> = b.sample_pool.iter().map(|i| pop[*i]).collect();
        assert_eq!(got, want);
    }
}

#[test]
fn real_distributions_match() {
    for b in &fixtures().seeds {
        let mut r = rng_for(b);
        let got = draw(&mut r, 5, |r| r.expovariate(1.0 / 45.0));
        assert_floats(&got, &b.expovariate, "expovariate", &b.seed);

        let mut r = rng_for(b);
        let got = draw(&mut r, 6, |r| r.gauss(0.0, 1.0));
        assert_gaussian_floats(&got, &b.gauss, &b.seed);

        let mut r = rng_for(b);
        let got = draw(&mut r, 6, |r| r.normalvariate(2.0, 3.0));
        assert_floats(&got, &b.normalvariate, "normalvariate", &b.seed);

        let mut r = rng_for(b);
        let got = draw(&mut r, 4, |r| r.triangular(1.0, 9.0, 3.0));
        assert_floats(&got, &b.triangular, "triangular", &b.seed);
    }
}

