#[test]
fn getstate_setstate_roundtrip() {
    for b in &fixtures().seeds {
        let mut r = rng_for(b);
        let first3 = draw(&mut r, 3, |r| r.random());
        assert_floats(&first3, &b.state_roundtrip.first3, "first3", &b.seed);
        let st = r.getstate();
        assert_eq!(
            st.index, b.state_roundtrip.index,
            "index for seed {:?}",
            b.seed
        );
        assert_eq!(&st.mt[..4], &b.state_roundtrip.mt_head[..]);
        assert_eq!(&st.mt[620..624], &b.state_roundtrip.mt_tail[..]);
        let after5 = draw(&mut r, 5, |r| r.random());
        assert_floats(&after5, &b.state_roundtrip.after5, "after5", &b.seed);
        r.setstate(&st);
        let restored5 = draw(&mut r, 5, |r| r.random());
        assert_floats(&restored5, &b.state_roundtrip.after5, "restored5", &b.seed);
        // A clone and from_state() are the same thing.
        let mut cloned = PyRandom::from_state(&st);
        let again = draw(&mut cloned, 5, |r| r.random());
        assert_floats(&again, &b.state_roundtrip.after5, "from_state", &b.seed);
        let c2 = cloned.clone();
        assert_eq!(c2, cloned);
    }
}

#[test]
fn gauss_next_survives_state() {
    for b in &fixtures().seeds {
        let mut r = rng_for(b);
        let g1 = r.gauss(0.0, 1.0);
        assert_gaussian_bits_close(
            g1.to_bits(),
            b.gauss_state.g1,
            &format!("gauss #1 for seed {:?}", b.seed),
        );
        let st = r.getstate();
        assert_gaussian_bits_close(
            st.gauss_next.expect("gauss caches the second draw"),
            b.gauss_state
                .gauss_next_bits
                .expect("fixture contains the cached second draw"),
            &format!("gauss_next in state for seed {:?}", b.seed),
        );
        let g2 = r.gauss(0.0, 1.0);
        assert_gaussian_bits_close(
            g2.to_bits(),
            b.gauss_state.g2,
            &format!("gauss #2 for seed {:?}", b.seed),
        );
        r.setstate(&st);
        assert_eq!(r.gauss(0.0, 1.0).to_bits(), g2.to_bits());
    }
}

