#[test]
fn sha256_prefix16_seeding_matches_traffic_manager() {
    for b in &fixtures().sha256_prefix16 {
        let seed: u64 = b.seed.parse().unwrap();
        assert_eq!(sha256_prefix16(&b.key), seed, "seed for {:?}", b.key);
        let mut r = PyRandom::new_from_sha256_prefix16(&b.key);
        let got = draw(&mut r, 5, |r| r.random());
        assert_floats(&got, &b.random, "sha256 random", &b.key);
    }
}

#[test]
fn int_seeding_paths_agree() {
    // Every int constructor is the same key once the magnitude is split.
    let a = PyRandom::new_from_i64(-5);
    let b = PyRandom::new_from_u64(5);
    let c = PyRandom::new_from_i128(5);
    let d = PyRandom::new_from_int_words(&[5, 0, 0]);
    let e = PyRandom::new_from_big_uint_le(&[5, 0, 0, 0, 0, 0, 0, 0, 0]);
    let f = init_by_array(&[5]);
    assert_eq!(a, b);
    assert_eq!(b, c);
    assert_eq!(c, d);
    assert_eq!(d, e);
    assert_eq!(e, f);
    // 2**32 is the two-word key [0, 1], not [1].
    let big = PyRandom::new_from_u64(1 << 32);
    assert_eq!(big, init_by_array(&[0, 1]));
    assert_ne!(big, init_by_array(&[1]));
    // Zero is the one-word key [0].
    assert_eq!(PyRandom::new_from_i64(0), init_by_array(&[0]));
    assert_eq!(int_words_from_le_bytes(&[]), vec![0]);
}

#[test]
fn seed_methods_reset_like_constructors() {
    let mut r = PyRandom::new_from_i64(1);
    let _ = r.random();
    r.seed_i64(7);
    assert_eq!(r, PyRandom::new_from_i64(7));
    r.seed_str("parking:0:12");
    assert_eq!(r, PyRandom::new_from_str("parking:0:12"));
}

#[test]
fn unseeded_generators_differ() {
    let mut a = PyRandom::new_unseeded();
    let mut b = PyRandom::new_unseeded();
    let sa: Vec<f64> = draw(&mut a, 4, |r| r.random());
    let sb: Vec<f64> = draw(&mut b, 4, |r| r.random());
    assert_ne!(sa, sb);
}

#[test]
fn floordiv_is_pythons() {
    assert_eq!(py_floordiv(7, 2), 3);
    assert_eq!(py_floordiv(-7, 2), -4);
    assert_eq!(py_floordiv(7, -2), -4);
    assert_eq!(py_floordiv(-7, -2), 3);
    assert_eq!(py_floordiv(6, -3), -2);
}

#[test]
fn bisect_right_is_pythons() {
    let a = [1.0, 3.0, 3.0, 10.0];
    assert_eq!(bisect_right(&a, 0.5, 0, 3), 0);
    assert_eq!(bisect_right(&a, 1.0, 0, 3), 1);
    assert_eq!(bisect_right(&a, 3.0, 0, 3), 3);
    assert_eq!(bisect_right(&a, 9.99, 0, 3), 3);
    assert_eq!(bisect_right(&a, 10.0, 0, 3), 3);
}
